    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 minSum) public {
        // Restrict values to reasonable range to avoid overflow and ensure Deposits work
        vm.assume(depositAmount > 0 && depositAmount < type(uint96).max);
        vm.assume(collectAmount > 0 && collectAmount < type(uint96).max);
        vm.assume(minSum > 0 && minSum < type(uint96).max);

        // Setup: initialize contract and set min sum
        address actor = address(0x1000);
        vm.deal(actor, depositAmount);
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFileDummy()));
        c.Initialized();

        // Actor deposits
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Assertion: After Deposit, actor's balance should be exactly depositAmount
        // In the mutant, Deposit never updates balances, so this assertion fails
        assertEq(c.balances(actor), depositAmount);

        // Additionally, verify Collect would succeed in correct version
        // This is not strictly needed for the assertion but confirms the property
        if (depositAmount >= minSum && depositAmount >= collectAmount) {
            uint256 balanceBefore = c.balances(actor);
            vm.prank(actor);
            c.Collect(collectAmount);
            assertEq(c.balances(actor), balanceBefore - collectAmount);
        }
    }
}

