pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 am1, uint256 am2, uint256 am3) public {
        // bound amounts to avoid overflow but keep wide
        am1 = bound(am1, 1, 1e36);
        am2 = bound(am2, 0, 1e36);
        am3 = bound(am3, 0, 1e36);

        // deploy a helper that will Deposit and Collect, and we track its balance changes
        // we use a precomputed address to control pranks
        address user = address(0x100);

        // first: initial setup
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFileHelper()));

        // user deposits am1
        vm.deal(user, am1);
        vm.prank(user);
        c.Deposit{value: am1}();

        // user deposits am2
        vm.deal(user, am2);
        vm.prank(user);
        c.Deposit{value: am2}();

        // user collects am3
        vm.prank(user);
        // ensure collect doesn't revert because of balance too low; we skip if balance insufficient
        uint256 userBal = c.balances(user);
        uint256 minSum = c.MinSum();
        if (userBal < am3 || userBal < minSum) {
            // cannot collect, so we stop here; invariant still must hold
            assertEq(address(c).balance, c.balances(user));
            return;
        }
        try c.Collect(am3) {} catch {}

        // after all operations, the total tracked balance (only user) equals contract ETH balance
        uint256 totalBal = c.balances(user);
        assertEq(address(c).balance, totalBal);
    }
}

